use std::{path::Path,error::Error};
fn stable_hash(v:&[u16])->i32{let(mut a,mut b)=(5381i32,5381i32);let mut i=0;while i<v.len()&&v[i]!=0{a=a.wrapping_mul(33)^v[i]as i32;if i==v.len()-1||v[i+1]==0{break;}b=b.wrapping_mul(33)^v[i+1]as i32;i+=2;}a.wrapping_add(b.wrapping_mul(1566083941))}
fn meadows_before_rivers(base:f32,n:[f32;5])->f32{let mut noise=(n[0]as f64*n[1]as f64)as f32;noise=(noise as f64+n[2]as f64*n[3]as f64*noise as f64*0.5)as f32;let mut h=(base as f64+noise as f64*0.1f32 as f64)as f32;let delta=(h as f64-0.15f32 as f64)as f32;let weight=(base as f64/0.4f32 as f64).clamp(0.,1.)as f32;if delta>0.{h=(h as f64-delta as f64*(1.-weight as f64)*0.75)as f32;}h}
fn after_rivers(river:f32,n:[f32;5])->f32{let h=(river as f64+n[3]as f64*0.01f32 as f64)as f32;(h as f64+n[4]as f64*0.003f32 as f64)as f32}
fn main()->Result<(),Box<dyn Error>>{let args=std::env::args().collect::<Vec<_>>();let dir=Path::new(args.get(1).ok_or("native checkpoint directory required")?);let mut hashes=0;for l in std::fs::read_to_string(dir.join("hashes.csv"))?.lines().skip(1){let(s,h)=l.split_once(',').ok_or("hash row")?;let utf=s.as_bytes().chunks_exact(4).map(|c|u16::from_str_radix(std::str::from_utf8(c).unwrap(),16).unwrap()).collect::<Vec<_>>();assert_eq!(stable_hash(&utf),h.parse::<i32>()?);hashes+=1;}let(mut count,mut before_error,mut after_error)=(0,0f32,0f32);for l in std::fs::read_to_string(dir.join("meadows.csv"))?.lines().skip(1){let p=l.split(',').map(str::parse::<f32>).collect::<Result<Vec<_>,_>>()?;let n=[p[3],p[4],p[5],p[6],p[7]];let before=meadows_before_rivers(p[2],n);let after=after_rivers(p[9],n);before_error=before_error.max((before-p[8]).abs());after_error=after_error.max((after-p[10]).abs());count+=1;}println!("Seed hash: {hashes} native UTF16 vectors matched");println!("Meadows arithmetic: {count} checkpoints, before-river max error={before_error}, final max error={after_error} normalized height units");println!("Native oracle inputs: base height, Unity Perlin samples, river output. This is NOT an independent full generator.");if count!=512||before_error>0.000001||after_error>0.000001{return Err("Meadows stage comparison failed".into());}Ok(())}
